import React from 'react';
import type { NavProps } from '../types';

const NAV_LINKS = [
  'stack',
  'skills',
  'experience',
  'projects',
  'contact',
] as const;

export function Nav({ t, isLight, toggle }: NavProps) {
  return (
    <nav
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 100,
        background: t.navBg,
        backdropFilter: 'blur(14px)',
        WebkitBackdropFilter: 'blur(14px)',
        borderBottom: `1px solid ${t.border}`,
        transition: 'background 0.35s, border-color 0.35s',
      }}
    >
      <div
        className='cv-inner'
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '18px 48px',
        }}
      >
        {/* Logo */}
        <div
          style={{
            fontFamily: 'Syne, sans-serif',
            fontSize: 18,
            fontWeight: 700,
            letterSpacing: '-0.02em',
            color: t.text,
          }}
        >
          SD<span style={{ color: t.purple }}>.</span>
        </div>

        {/* Links */}
        <ul
          style={{
            display: 'flex',
            gap: 28,
            listStyle: 'none',
            margin: 0,
            padding: 0,
          }}
        >
          {NAV_LINKS.map((s) => (
            <li key={s}>
              <a
                href={`#${s}`}
                style={{
                  fontSize: 11,
                  letterSpacing: '0.12em',
                  textTransform: 'uppercase',
                  color: t.text3,
                  textDecoration: 'none',
                  fontFamily: 'DM Mono, monospace',
                  transition: 'color 0.2s',
                }}
                onMouseEnter={(e) =>
                  ((e.target as HTMLAnchorElement).style.color = t.text)
                }
                onMouseLeave={(e) =>
                  ((e.target as HTMLAnchorElement).style.color = t.text3)
                }
              >
                {s}
              </a>
            </li>
          ))}
        </ul>

        {/* Right: status + toggle */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 20 }}>
          {/* Available dot */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              fontSize: 11,
              color: t.teal,
              letterSpacing: '0.08em',
              fontFamily: 'DM Mono, monospace',
            }}
          >
            <span
              style={{
                width: 6,
                height: 6,
                borderRadius: '50%',
                background: t.teal,
                display: 'inline-block',
                animation: 'pulse 2s infinite',
              }}
            />
            Available for work
          </div>

          {/* Theme toggle */}
          <button
            onClick={toggle}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 2,
              background: 'transparent',
              border: `1px solid ${t.border2}`,
              borderRadius: 100,
              padding: '4px 6px',
              cursor: 'pointer',
              transition: 'border-color 0.2s',
            }}
            title={isLight ? 'Switch to dark mode' : 'Switch to light mode'}
          >
            {/* Sun */}
            <span
              style={{
                fontSize: 13,
                lineHeight: 1,
                padding: '3px 6px',
                borderRadius: 100,
                background: isLight ? t.amberDim : 'transparent',
                boxShadow: isLight ? `0 0 8px 1px ${t.amber}88` : 'none',
                filter: isLight ? 'none' : 'grayscale(0.4) opacity(0.4)',
                transition: 'background 0.3s, box-shadow 0.3s, filter 0.3s',
              }}
            >
              ☀️
            </span>
            {/* Moon */}
            <span
              style={{
                fontSize: 13,
                lineHeight: 1,
                padding: '3px 6px',
                borderRadius: 100,
                background: !isLight ? t.purpleDim : 'transparent',
                boxShadow: !isLight ? `0 0 8px 1px ${t.purple}88` : 'none',
                filter: !isLight ? 'none' : 'grayscale(0.4) opacity(0.4)',
                transition: 'background 0.3s, box-shadow 0.3s, filter 0.3s',
              }}
            >
              🌙
            </span>
          </button>
        </div>
      </div>
    </nav>
  );
}
