import React from 'react';
import { Helmet } from 'react-helmet';
import type { Theme } from '../types';
import { DARK, LIGHT } from '../data';
import { themeRef } from '../components/scene';
import { usePersistentTheme } from '../hooks/usePersistentTheme';
// import { useVisitCounter } from '../hooks/useVisitCounter';
import { Nav } from '../components/Nav';
import {
  Hero,
  StackSection,
  SkillsSection,
  ExperienceSection,
  ProjectsSection,
  ContactSection,
} from '../components/sections';

// ThreeCanvas is only safe in the browser (no SSR / window)
// Gatsby's loadable with { ssr: false } pattern is the cleanest approach
import loadable from '@loadable/component';
const ThreeCanvas = loadable(
  () =>
    import('../components/scene').then((mod) => ({ default: mod.ThreeCanvas })),
  { ssr: false },
);

// ─── Page ─────────────────────────────────────────────────
export default function IndexPage() {
  const [isLight, toggle] = usePersistentTheme();
  //   useVisitCounter();
  const t: Theme = isLight ? LIGHT : DARK;

  // Sync theme to the mutable ref so R3F reads it every frame
  themeRef.current = t;

  const rootStyle: React.CSSProperties = {
    background: t.bg,
    color: t.text,
    fontFamily: 'DM Mono, monospace',
    fontSize: 14,
    lineHeight: 1.6,
    transition: 'background 0.35s ease, color 0.35s ease',
    minHeight: '100vh',
    position: 'relative',
  };

  return (
    <>
      <Helmet>
        <html lang='en' />
        <title>Sanj Di · Full Stack Developer</title>
        <link rel='icon' href='/favicon.ico' />
        <link rel='shortcut icon' href='/favicon.ico' />
        <meta
          name='description'
          content='Multi-disciplinary Full Stack Developer building scalable, cloud-native solutions. 10+ years in React, Vue, Node.js, NestJS, AWS and Azure.'
        />
        <meta name='viewport' content='width=device-width, initial-scale=1' />
        <meta property='og:title' content='Sanj Di · Full Stack Developer' />
        <meta
          property='og:description'
          content='Portfolio of Sanj Di — Full Stack Developer, Melbourne AU.'
        />
        <meta property='og:type' content='website' />
      </Helmet>

      <div style={rootStyle}>
        {/* Fixed R3F background — client-only, no SSR */}
        <ThreeCanvas />

        {/* UI layer */}
        <div style={{ position: 'relative', zIndex: 10 }}>
          <Nav t={t} isLight={isLight} toggle={toggle} />
          <main>
            <Hero t={t} />
            <StackSection t={t} />
            <SkillsSection t={t} />
            <ExperienceSection t={t} />
            <ProjectsSection t={t} />
            <ContactSection t={t} />
          </main>
          <footer
            style={{
              borderTop: `1px solid ${t.border}`,
              background: t.bg,
              transition: 'background 0.35s, border-color 0.35s',
            }}
          >
            <div
              className='cv-inner'
              style={{
                padding: '24px 48px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}
            >
              <span
                style={{
                  fontSize: 11,
                  color: t.text3,
                  letterSpacing: '0.04em',
                  fontFamily: 'DM Mono, monospace',
                }}
              >
                © 2026 Sanj Di. All rights reserved.
              </span>
              <span
                style={{
                  fontSize: 11,
                  color: t.text3,
                  letterSpacing: '0.04em',
                  fontFamily: 'DM Mono, monospace',
                }}
              >
                Built with Gatsby.js · Melbourne, AU
              </span>
            </div>
          </footer>
        </div>
      </div>
    </>
  );
}
